args.content:
* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, sans-serif;
  background: #faf8f5;
  color: #2b2b2b;
}

header {
  background: #4a3728;
  padding: 0.8rem 1.2rem;
}

header a {
  color: #fff;
  text-decoration: none;
  font-weight: 600;
  font-size: 1.1rem;
}

main {
  max-width: 640px;
  margin: 0 auto;
  padding: 1.2rem;
}

h2 {
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #7a6a5a;
  margin: 1.6rem 0 0.6rem;
}

.book {
  display: flex;
  align-items: center;
  gap: 0.8rem;
  background: #fff;
  border: 1px solid #e6ddd2;
  border-radius: 8px;
  padding: 0.7rem 0.9rem;
  margin-bottom: 0.5rem;
}

.book a.title {
  flex: 1;
  color: #2b2b2b;
  text-decoration: none;
  font-weight: 500;
}

.book a.title:hover { text-decoration: underline; }

.book .author { color: #8a7a6a; font-size: 0.85rem; }

.badge {
  font-size: 0.7rem;
  background: #e8f0e8;
  color: #3a6a3a;
  border-radius: 999px;
  padding: 0.15rem 0.5rem;
  white-space: nowrap;
}

button {
  font: inherit;
  border: 1px solid #c9b9a6;
  background: #fff;
  border-radius: 6px;
  padding: 0.3rem 0.7rem;
  cursor: pointer;
}

button:hover { background: #f1e9de; }

button.primary {
  background: #4a3728;
  border-color: #4a3728;
  color: #fff;
}

button.primary:hover { background: #5d4633; }

form {
  background: #fff;
  border: 1px solid #e6ddd2;
  border-radius: 8px;
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

input, textarea {
  font: inherit;
  border: 1px solid #d5c9b8;
  border-radius: 6px;
  padding: 0.45rem 0.6rem;
  background: #fff;
}

textarea { resize: vertical; min-height: 60px; }

.empty { color: #9a8a7a; font-style: italic; }

.detail-card {
  background: #fff;
  border: 1px solid #e6ddd2;
  border-radius: 8px;
  padding: 1.2rem;
}

.detail-card h1 { margin: 0 0 0.2rem; font-size: 1.4rem; }
.detail-card .author { color: #8a7a6a; margin: 0 0 1rem; }
.detail-card h3 { margin: 1.2rem 0 0.4rem; font-size: 0.85rem; text-transform: uppercase; color: #7a6a5a; }
.detail-card .notes { white-space: pre-wrap; margin: 0; }
.detail-actions { margin-top: 1.4rem; display: flex; gap: 0.5rem; }

.share-row { margin-top: 1rem; display: flex; gap: 0.5rem; align-items: center; }
.share-row input { flex: 1; color: #6a5a4a; font-size: 0.85rem; }

.error { color: #a33; margin-top: 0.5rem; }

