const app = document.getElementById("app");

function el(tag, attrs = {}, ...children) {
  const node = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k === "onClick") node.addEventListener("click", v);
    else node.setAttribute(k, v);
  }
  for (const child of children) node.append(child);
  return node;
}

const text = (s) => document.createTextNode(s);

async function api(path, opts = {}) {
  const res = await fetch(path, {
    headers: { "Content-Type": "application/json" },
    ...opts,
  });
  if (!res.ok) throw new Error((await res.json()).error || res.statusText);
  return res.json();
}

function bookRow(book) {
  const title = el("a", { class: "title", href: `/book/${book.id}` }, book.title);
  const author = el("span", { class: "author" }, book.author || "Unknown author");
  const parts = [title, author];
  if (book.status === "finished") {
    parts.push(el("span", { class: "badge" }, "finished"));
  } else {
    parts.push(
      el(
        "button",
        {
          onClick: async (e) => {
            e.preventDefault();
            await api(`/api/books/${book.id}`, {
              method: "PATCH",
              body: JSON.stringify({ status: "finished" }),
            });
            route();
          },
        },
        "Finished"
      )
    );
  }
