import { createServer } from "node:http";
import { readFile, mkdir } from "node:fs/promises";
import { randomUUID } from "node:crypto";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = dirname(fileURLToPath(import.meta.url));
const DATA_FILE = join(ROOT, "data", "books.json");
const PUBLIC_DIR = join(ROOT, "public");
const PORT = process.env.PORT || 3000;

async function loadBooks() {
  try {
    return JSON.parse(await readFile(DATA_FILE, "utf8"));
  } catch {
    return [];
  }
}

async function saveBooks(books) {
  await mkdir(dirname(DATA_FILE), { recursive: true });
  await writeFile(DATA_FILE, JSON.stringify(books, null, 2) + "\n");
}

function sendJson(res, status, body) {
  res.writeHead(status, { "Content-Type": "application/json" });
  res.end(JSON.stringify(body));
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let raw = "";
    req.on("data", (chunk) => {
      raw += chunk;
      if (raw.length > 1e6) {
        reject(new Error("Body too large"));
        req.destroy();
      }
    });
    req.on("end", () => {
      try {
        resolve(raw ? JSON.parse(raw) : {});
      } catch {
        reject(new Error("Invalid JSON"));
      }
    });
    req.on("error", reject);
  });
}

const MIME = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
};

async function serveStatic(res, path) {
  const file = path === "/" ? "index.html" : path.slice(1);
  try {
    const body = await readFile(join(PUBLIC_DIR, file));
    const ext = file.slice(file.lastIndexOf("."));
    res.writeHead(200, { "Content-Type": MIME[ext] || "application/octet-stream" });
    res.end(body);
  } catch {
    res.writeHead(404).end("Not found");
  }
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const path = url.pathname;

  try {
    if (path === "/api/books" && req.method === "GET") {
      return sendJson(res, 200, await loadBooks());
    }

    if (path === "/api/books" && req.method === "POST") {
      const { title, author = "", notes = "" } = await readBody(req);
      if (typeof title !== "string" || !title.trim()) {
        return sendJson(res, 400, { error: "title is required" });
      }
      const book = {
        id: randomUUID().slice(0, 8),
        title: title.trim(),
        author: String(author).trim(),
        notes: String(notes).trim(),
        status: "reading",
        addedAt: new Date().toISOString(),
      };
      const books = await loadBooks();
      books.push(book);
      await saveBooks(books);
      return sendJson(res, 201, book);
    }

    const bookMatch = path.match(/^\/api\/books\/([\w-]+)$/);
    if (bookMatch) {
      const books = await loadBooks();
      const book = books.find((b) => b.id === bookMatch[1]);
      if (!book) return sendJson(res, 404, { error: "book not found" });

      if (req.method === "GET") return sendJson(res, 200, book);

      if (req.method === "PATCH") {
        const patch = await readBody(req);
        if (patch.status === "finished" && book.status !== "finished") {
          book.status = "finished";
          book.finishedAt = new Date().toISOString();
        } else if (patch.status === "reading") {
          book.status = "reading";
          delete book.finishedAt;
        }
        if (typeof patch.notes === "string") book.notes = patch.notes.trim();
        await saveBooks(books);
        return sendJson(res, 200, book);
      }
    }

    if (req.method === "GET") {
      if (path.startsWith("/api/")) return sendJson(res, 404, { error: "not found" });
      if (path.startsWith("/assets/")) return serveStatic(res, path.slice(8));
      return serveStatic(res, "/");
    }

    sendJson(res, 405, { error: "method not allowed" });
  } catch (err) {
    sendJson(res, 400, { error: err.message });
  }
});

server.listen(PORT, () => {
  console.log(`Bookshelf running at http://localhost:${PORT}`);
});

